draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // two stick figures
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // figure 1
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/4 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/4 + 30, H/2 + 70);
  ctx.stroke();

  // figure 2
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 50);
  ctx.lineTo(W - W/4 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 50);
  ctx.lineTo(W - W/4 + 30, H/2 + 70);
  ctx.stroke();

  // bridge between them
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 20 * Math.sin(t), H/2 + 80);
  ctx.lineTo(W/2 + 50 - 20 * Math.sin(t), H/2 + 80);
  ctx.stroke();

  ctx.restore();
}
